"""In-process vulnerability alert exemptions for registered resources.

A vulnerability exception (exemption) records that a particular advisory
affecting a particular component on a particular resource is accepted. An
exception may only be created when it verbatim matches one of that
resource's recorded alerts on advisory identifier and component name,
case-sensitive and without any trimming or folding.

Records are kept per resource in registration order and are never
persisted: stopping or restarting the service clears every exception,
and no files are written. Updates and concurrency are intentionally out
of scope.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass

from .vulnerabilities import Vulnerability

#: Fields accepted by the registration request; all three are required.
_ALLOWED_FIELDS = frozenset({"advisory", "component", "reason"})
_REQUIRED_FIELDS = ("advisory", "component", "reason")


class VulnerabilityExceptionValidationError(ValueError):
    """An exemption registration payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class VulnerabilityExceptionError(ValueError):
    """An exemption operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class VulnerabilityException:
    """A single vulnerability alert exemption recorded against a resource."""

    id: str
    advisory: str
    component: str
    reason: str

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "advisory": self.advisory,
            "component": self.component,
            "reason": self.reason,
        }


def build_exception_fields(payload: object) -> tuple[str, str, str]:
    """Validate a decoded JSON payload and return the three field values.

    Returns ``(advisory, component, reason)``. All three must be present,
    non-empty strings; values are matched and echoed verbatim.
    """

    if not isinstance(payload, dict):
        raise VulnerabilityExceptionValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise VulnerabilityExceptionValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise VulnerabilityExceptionValidationError(
                f"Missing required field: {field!r}."
            )

    advisory = payload["advisory"]
    if not isinstance(advisory, str) or not advisory:
        raise VulnerabilityExceptionValidationError(
            "Field 'advisory' must be a non-empty string."
        )

    component = payload["component"]
    if not isinstance(component, str) or not component:
        raise VulnerabilityExceptionValidationError(
            "Field 'component' must be a non-empty string."
        )

    reason = payload["reason"]
    if not isinstance(reason, str) or not reason:
        raise VulnerabilityExceptionValidationError(
            "Field 'reason' must be a non-empty string."
        )

    return advisory, component, reason


def _matches_alert(
    advisory: str, component: str, alerts: list[Vulnerability]
) -> bool:
    """Verbatim, case-sensitive match on advisory and component."""

    for alert in alerts:
        if alert.advisory == advisory and alert.component == component:
            return True
    return False


class VulnerabilityExceptionStore:
    """Process-local, registration-ordered exemption storage per resource."""

    def __init__(self) -> None:
        # resource id -> exemptions in registration order.
        self._records: dict[str, list[VulnerabilityException]] = {}
        # resource id -> (advisory, component) pairs already exempted.
        self._keys: dict[str, set[tuple[str, str]]] = {}
        # resource id -> exception id -> index in the resource's list.
        self._ids: dict[str, dict[str, int]] = {}

    def reset(self) -> None:
        self._records = {}
        self._keys = {}
        self._ids = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove every exemption recorded for a resource.

        An unknown id is a no-op.
        """

        self._records.pop(resource_id, None)
        self._keys.pop(resource_id, None)
        self._ids.pop(resource_id, None)

    def add(
        self,
        resource_id: str,
        payload: object,
        alerts: list[Vulnerability],
    ) -> VulnerabilityException:
        """Validate and append an exemption for ``resource_id``.

        The advisory/component pair must verbatim match one of the
        resource's recorded ``alerts`` (case-sensitive). Raises
        :class:`VulnerabilityExceptionValidationError` for an invalid
        payload, :class:`VulnerabilityExceptionError` with code
        ``vulnerability_not_found`` when no alert matches, or code
        ``duplicate_exception`` when the same pair is already exempted for
        the resource. On any failure no exemption is recorded.
        """

        advisory, component, reason = build_exception_fields(payload)

        if not _matches_alert(advisory, component, alerts):
            raise VulnerabilityExceptionError(
                "vulnerability_not_found",
                "No vulnerability alert with the same advisory and "
                "component exists for this resource.",
            )

        key = (advisory, component)
        resource_keys = self._keys.setdefault(resource_id, set())
        if key in resource_keys:
            raise VulnerabilityExceptionError(
                "duplicate_exception",
                "An exception with the same advisory and component "
                "already exists for this resource.",
            )

        record = VulnerabilityException(
            id=uuid.uuid4().hex,
            advisory=advisory,
            component=component,
            reason=reason,
        )
        records = self._records.setdefault(resource_id, [])
        records.append(record)
        resource_keys.add(key)
        self._ids.setdefault(resource_id, {})[record.id] = len(records) - 1
        return record

    def list_for(self, resource_id: str) -> list[VulnerabilityException]:
        """Return a resource's exemptions in registration order."""

        return list(self._records.get(resource_id, ()))

    def exempted_keys(self, resource_id: str) -> set[tuple[str, str]]:
        """Return the set of exempted ``(advisory, component)`` pairs."""

        return set(self._keys.get(resource_id, frozenset()))

    def remove(
        self, resource_id: str, exception_id: str
    ) -> VulnerabilityException:
        """Remove and return the exemption identified by ``exception_id``.

        Raises :class:`VulnerabilityExceptionError` with code
        ``exception_not_found`` for an unknown or already deleted id; the
        stored records are left untouched.
        """

        records = self._records.get(resource_id)
        if records is None:
            raise VulnerabilityExceptionError(
                "exception_not_found",
                "No vulnerability exception exists with the requested id.",
            )
        index_map = self._ids.get(resource_id, {})
        index = index_map.get(exception_id)
        if index is None:
            raise VulnerabilityExceptionError(
                "exception_not_found",
                "No vulnerability exception exists with the requested id.",
            )
        record = records.pop(index)
        resource_keys = self._keys.get(resource_id)
        if resource_keys is not None:
            resource_keys.discard((record.advisory, record.component))
        index_map.pop(exception_id, None)
        # Reindex the remaining ids after the list shifted.
        for position, remaining in enumerate(records):
            index_map[remaining.id] = position
        return record

