            environ, raw_id, start_response
        )
    if method == "GET":
        return _handle_vulnerability_exceptions_get(
            environ, raw_id, start_response
        )
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


